64	// Client-side guard: a mount path is copyable only if it's a plain absolute path
65	// (named Docker volumes and other non-paths are shown but never selected). The
66	// server re-validates every selected path against the strict allowlist regardless.
67	function isCopyablePath(p: string): boolean {
68	  return typeof p === "string" && p.startsWith("/") && !p.includes("..") && p.length > 1;
69	}
70	
71	// ---- Storage-guardrail helpers --------------------------------------------
72	const GiB = 1024 ** 3;
73	
74	/** Parse a human size label ("1.2G", "340M", "220 MB") into bytes. Mirrors the
75	 *  server's parseSizeLabel — kept local so the client never imports the ssh2-laden
76	 *  detection module. */
77	function parseSize(label: string): number {
78	  const m = /^([\d.]+)\s*([KMGT]?)/i.exec((label ?? "").trim());
79	  if (!m) return 0;
80	  const n = parseFloat(m[1]);
81	  const mult: Record<string, number> = { "": 1, K: 1024, M: 1024 ** 2, G: 1024 ** 3, T: 1024 ** 4 };
82	  return n * (mult[m[2].toUpperCase()] ?? 1);
83	}
84	
85	/** Adaptive size formatter: GB for ≥1 GB, else MB. */
86	function fmtSize(bytes: number): string {
87	  if (!Number.isFinite(bytes) || bytes <= 0) return "0 MB";
88	  const g = bytes / GiB;
89	  if (g >= 1) return g >= 10 ? `${g.toFixed(0)} GB` : `${g.toFixed(1)} GB`;
90	  const mb = bytes / (1024 * 1024);
91	  return `${Math.max(1, Math.round(mb))} MB`;
92	}
93	
94	// ---- OS/architecture compatibility helpers --------------------------------
95	/** Collapse arch aliases so amd64≡x86_64 and arm64≡aarch64 compare equal. */
96	function normArch(a: string | null | undefined): string {
97	  const s = (a ?? "").toLowerCase();
98	  if (!s) return "";
99	  if (["x86_64", "amd64", "x64"].includes(s)) return "x86_64";
100	  if (["aarch64", "arm64"].includes(s)) return "arm64";
101	  if (s.startsWith("armv") || s === "armhf" || s === "arm") return "arm";
102	  if (["i386", "i686", "x86"].includes(s)) return "x86";
103	  return s;
104	}
105	
106	const FAMILY_IDS: Record<string, string[]> = {
107	  debian: ["debian", "ubuntu", "linuxmint", "pop", "raspbian", "devuan", "kali", "elementary", "zorin"],
108	  rhel: ["rhel", "centos", "almalinux", "rocky", "fedora", "ol", "oracle", "amzn", "scientific", "cloudlinux"],
109	  suse: ["opensuse", "opensuse-leap", "opensuse-tumbleweed", "sles", "suse"],
110	  arch: ["arch", "manjaro", "endeavouros"],
111	  alpine: ["alpine"],
112	};
113	const FAMILY_LABEL: Record<string, string> = {
114	  debian: "Debian / Ubuntu",
115	  rhel: "RHEL / CentOS / Alma / Rocky",
116	  suse: "openSUSE / SLES",
117	  arch: "Arch",
118	  alpine: "Alpine",
119	  other: "another",
120	};
121	/** Map an os-release ID (or an osTemplate family string) to a distro family key. */
122	function familyOf(id: string | null | undefined): string {
123	  const s = (id ?? "").toLowerCase();
124	  if (!s) return "";
125	  for (const [fam, ids] of Object.entries(FAMILY_IDS)) if (ids.includes(s)) return fam;
126	  return "other";
127	}
128	
129	/** Pick the closest OS template to the source distro: same family first (prefer a
130	 *  matching major version), else nothing. Returns the template or null. */
131	function closestOsTemplate(
132	  sourceId: string,
133	  sourceVersion: string,
134	  templates: OsTemplateOption[]
135	): OsTemplateOption | null {
136	  const fam = familyOf(sourceId);
137	  if (!fam || fam === "other") return null;
138	  const sameFamily = templates.filter((t) => familyOf(t.family) === fam);
139	  if (sameFamily.length === 0) return null;
140	  const srcMajor = (sourceVersion || "").split(".")[0];
141	  // Prefer an exact family + same-major-version match, else the same family.
142	  const exact = sameFamily.find((t) => (t.version || "").split(".")[0] === srcMajor && srcMajor);
143	  return exact ?? sameFamily[0];
144	}
