182	/** A single pre-checked item row (web root / home dir / database). */
183	function CheckItem({
184	  checked,
185	  onToggle,
186	  title,
187	  sub,
188	  size,
189	  badge,
190	}: {
191	  checked: boolean;
192	  onToggle: () => void;
193	  title: string;
194	  sub?: string;
195	  size?: string;
196	  badge?: React.ReactNode;
197	}) {
