199	    <label
200	      className={`flex cursor-pointer items-center gap-3 rounded-xl border px-3 py-2.5 transition ${
201	        checked ? "border-brand-400/50 bg-brand-500/[0.07]" : "border-white/10 bg-white/[0.02] hover:border-white/20"
202	      }`}
