210	      <div className="min-w-0 flex-1">
211	        <div className="flex items-center gap-2">
212	          <span className="truncate font-mono text-xs text-slate-200">{title}</span>
213	          {badge}
214	        </div>
215	        {sub && <p className="truncate text-[11px] text-slate-500">{sub}</p>}
216	      </div>
217	      {size && <span className="shrink-0 text-xs font-medium text-slate-400">{size}</span>}
218	    </label>
219	  );
220	}
221	
222	export function MigrationWizard({
223	  servers,
224	  osTemplates = [],
225	}: {
226	  servers: ServerOption[];
227	  osTemplates?: OsTemplateOption[];
228	}) {
229	  const [step, setStep] = useState(0);
230	  const [error, setError] = useState<string | null>(null);
231	  const [scanning, setScanning] = useState(false);
232	  const [submitting, setSubmitting] = useState(false);
233	  const [activeId, setActiveId] = useState<string | null>(null);
234	
235	  // Step 0 — destination
236	  const [serverId, setServerId] = useState(servers[0]?.id ?? "");
237	  // Step 1 — source
238	  const [host, setHost] = useState("");
239	  const [port, setPort] = useState("22");
240	  const [user, setUser] = useState("root");
241	  const [password, setPassword] = useState("");
242	
243	  // Step 2 — detection results + selections
244	  const [scan, setScan] = useState<ScanResult | null>(null);
245	  // Target free-space + OS/arch probe (for storage & compatibility guardrails).
246	  // undefined = not yet fetched; a value with disk:null = probe failed (soft warn).
247	  const [targetInfo, setTargetInfo] = useState<TargetInfo | null | undefined>(undefined);
248	  const [webSel, setWebSel] = useState<Set<string>>(new Set());
249	  const [homeSel, setHomeSel] = useState<Set<string>>(new Set());
250	  const [appSel, setAppSel] = useState<Set<string>>(new Set());
251	  const [dockerSel, setDockerSel] = useState<Set<string>>(new Set());
252	  const [customPaths, setCustomPaths] = useState<string[]>([]);
253	  const [newPath, setNewPath] = useState("");
254	  // Explicit opt-in to spend an attached block-storage volume on Docker's data.
255	  // OFF by default and never flipped on automatically: while a volume holds
256	  // /var/lib/docker the server can't run without it, so it stops being the
257	  // portable, move-it-to-another-server add-on the Volumes page promises.
258	  const [useVolumeForDocker, setUseVolumeForDocker] = useState(false);
259	
260	  // Deep-link back into a migration's result view (?migration=<id>). Used when a
261	  // customer leaves for Cloudflare's consent screen from the completed-migration
262	  // panel — they come back to exactly where they were, not to a blank wizard.
263	  useEffect(() => {
264	    const id = new URLSearchParams(window.location.search).get("migration");
265	    if (id && /^[A-Za-z0-9_-]{6,64}$/.test(id)) setActiveId(id);
266	  }, []);
267	
268	  const hostValid = /^[a-zA-Z0-9.\-:[\]]+$/.test(host.trim()) && host.trim().length > 0;
269	  const portNum = Number(port);
270	  const portValid = Number.isInteger(portNum) && portNum >= 1 && portNum <= 65535;
271	  const canScan = hostValid && portValid && user.trim().length > 0 && password.length > 0;
272	
273	  async function runScan() {
274	    setError(null);
275	    setScanning(true);
276	    setTargetInfo(undefined);
277	    try {
278	      // Scan the source and probe the destination's free space in parallel.
279	      const [res, diskRes] = await Promise.all([
280	        scanSource({
281	          serverId,
282	          sourceHost: host.trim(),
283	          sourcePort: portNum,
284	          sourceUser: user.trim(),
285	          sourcePassword: password,
286	        }),
287	        targetDiskFree(serverId).catch(() => ({ info: undefined })),
288	      ]);
289	      if (res.error) {
290	        setError(res.error);
291	        return;
292	      }
293	      setTargetInfo(diskRes?.info ?? null);
294	      const s = res.scan!;
295	      setScan(s);
296	      // Pre-check everything we found — the customer just unchecks what they don't want.
297	      setWebSel(new Set(s.webRoots.map((w) => w.path)));
298	      setHomeSel(new Set(s.homes.map((h) => h.path)));
299	      setAppSel(new Set(s.appDirs.map((a) => a.path)));
300	      // Docker bind-mount host paths are the container's data — pre-check the copyable ones.
301	      setDockerSel(new Set(s.containers.flatMap((c) => c.mounts.filter(isCopyablePath))));
302	      setCustomPaths([]);
303	      setStep(2);
304	    } catch {
305	      setError("Something went wrong while scanning. Please try again.");
306	    } finally {
307	      setScanning(false);
308	    }
309	  }
310	
311	  function toggle(set: Set<string>, key: string, apply: (s: Set<string>) => void) {
312	    const next = new Set(set);
313	    if (next.has(key)) next.delete(key);
314	    else next.add(key);
315	    apply(next);
316	  }
317	
318	  function addPath() {
319	    const p = newPath.trim();
320	    if (p && p.startsWith("/") && !customPaths.includes(p)) {
321	      setCustomPaths((list) => [...list, p]);
322	      setNewPath("");
323	    }
324	  }
325	
326	  const selectedPaths = useMemo(
327	    () => [...new Set([...webSel, ...homeSel, ...appSel, ...dockerSel, ...customPaths])],
328	    [webSel, homeSel, appSel, dockerSel, customPaths]
329	  );
330	  // Databases are auto-included whenever an engine is detected — no password, no
331	  // per-DB selection. We dump every database via root's local auth on the source.
332	  const detectedEngines = useMemo(
333	    () => [...new Set((scan?.engines ?? []).filter((e) => e.present).map((e) => e.engine))],
334	    [scan]
335	  );
336	  // Prerequisites we'll install on the new server, derived from what we found.
337	  const prereqs = useMemo(() => {
338	    const list: string[] = [];
339	    if (!scan) return list;
340	    if (detectedEngines.includes("mysql")) list.push("MySQL / MariaDB");
341	    if (detectedEngines.includes("postgres")) list.push("PostgreSQL");
342	    if (scan.containers.length > 0) list.push("Docker + Compose");
343	    const procBlob = [
344	      ...scan.ports.map((p) => p.proc || ""),
345	      ...scan.services.map((s) => s.name || ""),
346	    ]
347	      .join(" ")
348	      .toLowerCase();
349	    if (/nginx/.test(procBlob) || (!/apache|httpd/.test(procBlob) && scan.webRoots.length > 0)) list.push("nginx");
350	    if (/apache|httpd/.test(procBlob)) list.push("Apache");
351	    const rtBlob = [
352	      ...scan.appDirs.map((a) => a.runtime || ""),
353	      ...scan.ports.map((p) => p.proc || ""),
354	    ]
355	      .join(" ")
356	      .toLowerCase();
357	    if (/node|next|pm2/.test(rtBlob)) list.push("Node.js");
358	    if (/python|gunicorn|uvicorn|celery/.test(rtBlob)) list.push("Python 3");
359	    return [...new Set(list)];
360	  }, [scan, detectedEngines]);
361	
362	  const hasSelection = selectedPaths.length > 0 || detectedEngines.length > 0;
363	
364	  // ---- Storage guardrail — total to migrate vs. target free space ----------
365	  // Recomputes live as the customer checks/unchecks. Unknown-size items (custom
366	  // folders, Docker mounts) contribute 0; the DB estimate is added whenever an
367	  // engine is detected (databases are auto-included).
368	  /**
369	   * The move splits across two destinations, so we size them separately:
370	   *  - `fileBytes`   → the selected folders + databases, restored to their original
371	   *                    paths, i.e. onto the ROOT filesystem.
372	   *  - `dockerBytes` → Docker images (they unpack to roughly 2x while loading) plus
373	   *                    the NAMED VOLUMES they mount (copied verbatim, so no unpack
374	   *                    factor) plus working headroom, all of which live under
375	   *                    /var/lib/{docker,containerd} — the engine relocates those onto
376	   *                    an unused volume, but ONLY if the customer opts in to using it.
377	   * Nothing ever needs `fileBytes + dockerBytes` contiguously, so testing the
378	   * combined total against a single disk understates what actually fits.
379	   *
380	   * `dockerBytes` MUST mirror worker/migrate-real.ts' pre-flight
381	   * (`inv.imageBytes * IMAGE_OVERHEAD_FACTOR + inv.volumeBytes`, then `+ FS_HEADROOM`)
382	   * exactly, and the volume bytes MUST stay out of `f`: quoting less than the engine
383	   * demands refuses a committed migration, quoting more spends disk that was never
384	   * needed. Both directions have happened. test/migration-sizing.test.ts pins it.
385	   */
386	  const { fileBytes, dockerBytes, totalBytes } = useMemo(() => {
387	    if (!scan) return { fileBytes: 0, dockerBytes: 0, totalBytes: 0 };
388	    const byPath = new Map<string, number>();
389	    scan.webRoots.forEach((w) => byPath.set(w.path, parseSize(w.sizeLabel)));
390	    scan.homes.forEach((h) => byPath.set(h.path, parseSize(h.sizeLabel)));
391	    scan.appDirs.forEach((a) => byPath.set(a.path, parseSize(a.sizeLabel)));
392	    let f = 0;
393	    for (const p of selectedPaths) f += byPath.get(p) ?? 0;
394	    if (detectedEngines.length > 0) f += Math.max(0, scan.dbSizeBytes ?? 0);
395	    const imageBytes = Math.max(0, scan.dockerImageBytes ?? 0);
396	    const volumeBytes = Math.max(0, scan.dockerVolumeBytes ?? 0);
397	    const d = imageBytes > 0 || volumeBytes > 0 ? imageBytes * 2 + volumeBytes + 2 * GiB : 0;
398	    return { fileBytes: f, dockerBytes: d, totalBytes: f + d };
399	  }, [scan, selectedPaths, detectedEngines]);
400	
401	  const storage = useMemo(() => {
402	    const disk = targetInfo?.disk ?? null;
403	    // Capacity sitting in an unused volume — OFFERED, not counted. It is the
404	    // largest single volume (the engine uses exactly one and never combines
405	    // them), and it only becomes usable space once the customer opts in.
406	    const spareOffered = Math.max(0, targetInfo?.spareDiskBytes ?? 0);
407	    const spareCount = Math.max(0, targetInfo?.spareDiskCount ?? 0);
408	    if (!disk) {
409	      return {
410	        state: "unknown" as StorageState,
411	        avail: 0, rootAvail: 0, spare: 0, spareOffered, spareCount,
412	        total: 0, diskTotal: 0, used: 0, margin: 0, deficitGB: 0,
413	      };
414	    }
415	    // The volume counts as capacity ONLY with explicit consent. Without it the
416	    // fit test is root-only: taking a portable volume to make a migration fit is
417	    // the customer's decision, so the verdict must reflect what they actually
418	    // chose rather than what we could do if we helped ourselves to their disk.
419	    const spare = useVolumeForDocker ? spareOffered : 0;
420	    const rootAvail = disk.availBytes;
421	    // Where each portion actually lands: files always on root; Docker's stores on
422	    // the volume when the customer opted in, otherwise also on root. Sizing the
423	    // two destinations separately is why opting in genuinely adds capacity even
424	    // though the root disk and the volume are separate filesystems.
425	    const dockerTarget = spare > 0 ? spare : rootAvail;
426	    const rootNeed = spare > 0 ? fileBytes : fileBytes + dockerBytes;
427	    const avail = spare > 0 ? rootAvail + spare : rootAvail;
428	    // Leave headroom for the OS/overhead: the larger of 2 GB or 10% of free space.
429	    const margin = Math.max(2 * GiB, rootAvail * 0.1);
430	    // The tighter of the two destinations decides the verdict.
431	    const rootSlack = rootAvail - rootNeed;
432	    const dockerSlack = dockerTarget - dockerBytes;
433	    const worstSlack = Math.min(rootSlack, dockerBytes > 0 ? dockerSlack : Infinity);
434	    let state: StorageState;
435	    if (worstSlack < 0) state = "wontfit";
436	    else if (worstSlack < margin) state = "tight";
437	    else state = "comfortable";
438	    // Extra space needed on whichever destination is short (data + margin).
439	    const deficitGB = Math.max(1, Math.ceil((margin - worstSlack) / GiB));
440	    return {
441	      state, avail, rootAvail, spare, spareOffered, spareCount,
442	      total: totalBytes, diskTotal: disk.totalBytes, used: disk.usedBytes, margin, deficitGB,
443	    };
444	  }, [targetInfo, totalBytes, useVolumeForDocker]);
445	
446	  // Hard block only when the data physically won't fit on the destination.
447	  const storageBlocks = storage.state === "wontfit";
448	
449	  // ---- OS / architecture compatibility (static — based on the scan) --------
450	  const compat = useMemo(() => {
451	    const items: CompatItem[] = [];
452	    const srcOs = scan?.sourceOs ?? null;
453	    const srcArch = scan?.sourceArch ?? null;
454	    const tgtArch = targetInfo?.arch ?? null;
455	    const tgtOs = targetInfo?.os ?? null;
456	
457	    const sa = normArch(srcArch);
458	    const ta = normArch(tgtArch);
459	    const archMismatch = !!sa && !!ta && sa !== ta;
460	
461	    const sFam = familyOf(srcOs?.id);
462	    const tFam = familyOf(tgtOs?.id);
463	    const familyMismatch = !!sFam && !!tFam && sFam !== tFam;
464	    const sameFamilyDiffMajor =
465	      !!sFam && sFam === tFam && !!srcOs?.versionId && !!tgtOs?.versionId &&
466	      srcOs.versionId.split(".")[0] !== tgtOs.versionId.split(".")[0];
467	
468	    if (archMismatch) {
469	      items.push({
470	        level: "critical",
471	        title: `Different CPU architecture (${sa} → ${ta})`,
472	        body: (
473	          <>
474	            Your old server is <span className="font-mono">{sa}</span> but your Nxeon server is{" "}
