1463	  "co.uk", "org.uk", "ac.uk", "gov.uk", "me.uk", "com.au", "net.au", "org.au",
1464	  "co.nz", "com.br", "com.mx", "com.ar", "co.za", "co.in", "co.jp", "com.sg",
