1471	  if (labels.length <= 2) return labels.join(".");
1472	  const lastTwo = labels.slice(-2).join(".");
1473	  return MULTI_LABEL_SUFFIXES.includes(lastTwo) ? labels.slice(-3).join(".") : lastTwo;
