542	/**
543	 * Per-domain SPF / DKIM / DMARC / MX self-check.
544	 *
545	 * WHY: "my mail goes to spam" was undiagnosable from inside the product. The
546	 * platform owner hit exactly this and had to diagnose it with an external
547	 * third-party tool, so every customer in the same position had no route at all.
548	 *
549	 * Two things this panel must never do, because both would make it the codebase's
550	 * recurring defect in a new place — a surface reporting an outcome it never
551	 * verified, here telling someone their mail is fine while it goes to spam:
552	 *
553	 *   1. Report a status the server did not derive from DNS. Every badge below
554	 *      comes from `checkEmailDeliverability`, which reads the zone's own
555	 *      AUTHORITATIVE nameservers (this host's `hosts: files myhostname dns`
556	 *      nsswitch order can answer a lookup out of /etc/hosts while looking like a
557	 *      real query — that produced one confidently wrong diagnosis already).
558	 *   2. Round a partial answer up. `unknown` renders as its own slate state, not
559	 *      as a pass, and the nameservers actually queried are printed so the result
560	 *      is auditable rather than taken on trust.
561	 *
562	 * Not auto-run: each check is several outbound DNS queries plus one Mailcow call,
563	 * and the customer has to be looking at it for the answer to be useful.
564	 */
565	function DeliverabilityPanel({
566	  subscriptionId,
567	  domainName,
568	}: {
569	  subscriptionId: string;
570	  domainName: string;
571	}) {
572	  const [report, setReport] = useState<DeliverabilityReport | null>(null);
573	  const [error, setError] = useState<string | null>(null);
574	  const [pending, start] = useTransition();
575	
576	  function run() {
577	    setError(null);
578	    start(async () => {
579	      const res = await checkEmailDeliverability(subscriptionId);
580	      if (res?.error) {
581	        setError(res.error);
582	        setReport(null);
583	      } else if (res?.report) {
584	        setReport(res.report);
585	      }
586	    });
587	  }
588	
589	  const failing = report?.checks.filter((c) => c.status === "fail").length ?? 0;
590	  const warning = report?.checks.filter((c) => c.status === "warn").length ?? 0;
591	  const unknown = report?.checks.filter((c) => c.status === "unknown").length ?? 0;
592	
593	  return (
594	    <div className="mt-3 rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
595	      <div className="flex flex-wrap items-center justify-between gap-2">
596	        <div className="flex flex-wrap items-center gap-2">
597	          <span className="text-sm font-semibold text-white">Deliverability check</span>
598	          {report &&
599	            (failing > 0 ? (
600	              <Badge tone="red">
601	                {failing} problem{failing === 1 ? "" : "s"}
602	              </Badge>
603	            ) : unknown > 0 ? (
604	              <Badge tone="slate">Incomplete</Badge>
605	            ) : warning > 0 ? (
606	              <Badge tone="amber">
607	                {warning} warning{warning === 1 ? "" : "s"}
608	              </Badge>
609	            ) : (
610	              <Badge tone="green">All checks pass</Badge>
611	            ))}
612	        </div>
613	        <button className="btn-secondary py-1 text-xs" onClick={run} disabled={pending}>
614	          {pending ? "Checking DNS…" : report ? "Re-check" : "Check deliverability"}
615	        </button>
616	      </div>
617	
618	      <p className="mt-2 text-xs text-slate-400">
619	        Checks what <span className="font-mono">{domainName}</span> actually publishes for MX, SPF, DKIM
620	        and DMARC. If your mail is landing in spam, a failing row here is usually why.
621	      </p>
622	
623	      {error && (
624	        <div className="mt-2 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-400">
625	          {error}
626	        </div>
627	      )}
628	
629	      {report && (
630	        <div className="mt-3 space-y-2">
631	          {report.error && (
632	            <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
633	              {report.error}
634	            </div>
635	          )}
636	
637	          {report.checks.map((c) => (
638	            <div key={c.key} className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
639	              <div className="flex flex-wrap items-center gap-2">
640	                <Badge tone={CHECK_TONE[c.status]}>{CHECK_LABEL[c.status]}</Badge>
641	                <span className="text-sm font-medium text-slate-200">{c.label}</span>
642	                <span className="text-[11px] text-slate-500">
643	                  {c.type} · <span className="font-mono">{c.host}</span>
644	                </span>
645	              </div>
646	
647	              <div className="mt-2 grid gap-2 sm:grid-cols-2">
648	                <div className="min-w-0">
649	                  <div className="text-[11px] uppercase tracking-wide text-slate-500">Found</div>
650	                  <code className="mt-0.5 block break-all rounded bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-slate-200">
651	                    {c.observed || "— nothing published —"}
652	                  </code>
653	                </div>
654	                <div className="min-w-0">
655	                  <div className="text-[11px] uppercase tracking-wide text-slate-500">Expected</div>
656	                  <code className="mt-0.5 block break-all rounded bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-slate-200">
657	                    {c.expected || "—"}
658	                  </code>
659	                </div>
660	              </div>
661	
662	              <p
663	                className={`mt-2 text-xs ${
664	                  c.status === "fail"
665	                    ? "text-red-400"
666	                    : c.status === "warn"
667	                      ? "text-amber-400"
668	                      : c.status === "pass"
669	                        ? "text-emerald-300/80"
670	                        : "text-slate-400"
671	                }`}
672	              >
673	                {c.detail}
674	              </p>
675	            </div>
676	          ))}
677	
678	          {/* Printing the nameservers is the point, not decoration: it is how the
679	              customer (or support) can tell this answer came from the zone's own
680	              authority and not from a stale recursive cache. */}
681	          <p className="text-[11px] text-slate-500">
682	            {report.nameservers.length > 0 ? (
683	              <>
684	                Read directly from this domain&apos;s nameservers (
685	                <span className="font-mono">{report.nameservers.join(", ")}</span>), so a record you
686	                just changed shows up straight away.
687	              </>
688	            ) : (
689	              <>Couldn&apos;t reach this domain&apos;s nameservers, so no record could be read.</>
690	            )}{" "}
691	            Checked {new Date(report.checkedAt).toLocaleTimeString()}.
692	          </p>
693	        </div>
694	      )}
695	    </div>
696	  );
697	}
