274	    setMode("maximized");
275	  }, []);
276	
277	  const focusSession = useCallback((id: string) => {
278	    setActiveId(id);
279	    setMode((m) => (m === "minimized" ? "minimized" : "maximized"));
280	  }, []);
281	
282	  const closeSession = useCallback(
283	    (id: string) => {
284	      const live = liveRef.current.get(id);
285	      if (live) teardownLive(live);
286	      liveRef.current.delete(id);
287	      setErrors((prev) => {
288	        if (!prev[id]) return prev;
289	        const next = { ...prev };
290	        delete next[id];
291	        return next;
292	      });
293	      setSessions((prev) => {
294	        const next = prev.filter((s) => s.id !== id);
295	        if (next.length === 0) {
