306	
307	  const minimize = useCallback(() => setMode("minimized"), []);
308	  const restore = useCallback(() => setMode("maximized"), []);
309	
310	  const close = useCallback(() => {
311	    for (const live of liveRef.current.values()) teardownLive(live);
312	    liveRef.current.clear();
313	    setSessions([]);
314	    setActiveId(null);
315	    setErrors({});
316	    setMode("hidden");
317	  }, [teardownLive]);
318	
319	  /** Reconnect a session in place (keeps its tab + persistent container). */
320	  const reconnect = useCallback(
321	    (id: string) => {
322	      const live = liveRef.current.get(id);
323	      if (!live) return;
324	      try {
325	        live.ro?.disconnect();
326	      } catch {
327	        /* ignore */
328	      }
329	      live.ro = null;
330	      try {
331	        live.ws?.close();
332	      } catch {
333	        /* ignore */
334	      }
335	      live.ws = null;
336	      try {
337	        live.term?.dispose();
338	      } catch {
339	        /* ignore */
340	      }
341	      live.term = null;
342	      live.fit = null;
343	      live.starting = false;
344	      live.container.innerHTML = "";
345	      void connect(id);
346	    },
347	    [connect]
348	  );
349	
350	  /** Mount slot: append the session's persistent container, kick off connect. */
351	  const attach = useCallback(
352	    (id: string, el: HTMLDivElement | null) => {
353	      const live = liveRef.current.get(id);
354	      if (!live || !el) return; // on unmount (el === null) we keep the container alive
355	      if (live.container.parentElement !== el) {
356	        el.appendChild(live.container);
357	      }
358	      if (!live.term && !live.starting) void connect(id);
359	    },
360	    [connect]
361	  );
362	
363	  // Refit the active session whenever it becomes visible or the dock resizes.
364	  useEffect(() => {
