63	}
64	
65	function daysUntil(iso: string | null): number | null {
66	  if (!iso) return null;
67	  return Math.floor((new Date(iso).getTime() - Date.now()) / DAY_MS);
68	}
69	
70	function ago(iso: string): string {
71	  const mins = Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 60_000));
72	  if (mins < 1) return "just now";
73	  if (mins === 1) return "1 minute ago";
74	  if (mins < 60) return `${mins} minutes ago`;
75	  const hrs = Math.round(mins / 60);
76	  return hrs === 1 ? "1 hour ago" : `${hrs} hours ago`;
