300	// ---------------------------------------------------------------------------
301	// Row actions
302	// ---------------------------------------------------------------------------
303	
304	function CertActions({ cert }: { cert: CertRow }) {
305	  const [error, setError] = useState<string | null>(null);
306	  const [pending, start] = useTransition();
307	
308	  const run = (fn: () => Promise<{ error?: string }>, confirmMsg?: string) => {
309	    if (confirmMsg && !window.confirm(confirmMsg)) return;
310	    start(async () => {
311	      setError(null);
312	      const res = await fn();
313	      if (res?.error) setError(res.error);
314	    });
315	  };
316	
317	  // Only a genuinely executing certbot run blocks deletion. A row stranded in
318	  // ISSUING by a dead worker must be clearable, or the customer can never
319	  // request that domain again.
320	  const issuingNow = cert.status === "ISSUING" && cert.queue?.state === "running";
321	  const canRenew = ["ACTIVE", "EXPIRED", "FAILED"].includes(cert.status);
322	
323	  return (
324	    <div className="flex flex-col items-end gap-1.5">
325	      <div className="flex items-center gap-2">
326	        <button
327	          type="button"
328	          role="switch"
329	          aria-checked={cert.autoRenew}
330	          aria-label="Toggle auto-renew"
331	          disabled={pending}
332	          onClick={() => run(() => toggleAutoRenew(cert.id))}
333	          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${
334	            cert.autoRenew ? "bg-brand-500" : "bg-white/15"
335	          } ${pending ? "opacity-60" : ""}`}
336	        >
337	          <span
338	            className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition-transform ${
339	              cert.autoRenew ? "translate-x-5" : "translate-x-0.5"
340	            }`}
341	          />
342	        </button>
343	        {canRenew && (
344	          <button
345	            className="btn-ghost px-3 py-1 text-xs"
346	            disabled={pending}
347	            onClick={() =>
348	              run(
349	                () => renewCertificate(cert.id),
350	                `Reissue the certificate for "${cert.domain}" now? Let's Encrypt allows only 5 identical ` +
351	                  `certificates per week, so use this sparingly.`
352	              )
353	            }
354	          >
355	            Renew now
356	          </button>
357	        )}
358	        <button
359	          className="btn-danger px-3 py-1 text-xs"
360	          disabled={pending || issuingNow}
361	          title={issuingNow ? "certbot is running for this domain right now" : undefined}
362	          onClick={() =>
363	            run(
364	              () => deleteCertificate(cert.id),
365	              `Delete the certificate for "${cert.domain}"? This removes it from your account.`
366	            )
367	          }
368	        >
369	          Delete
370	        </button>
371	      </div>
372	      {!cert.autoRenew && (
373	        <span className="text-xs text-slate-500">
374	          Auto-renew off — this will not be replaced before it expires.
375	        </span>
376	      )}
377	      {error && <span className="max-w-md text-right text-xs text-red-400">{error}</span>}
378	    </div>
379	  );
380	}
