424	                <th>Expires (observed)</th>
425	                <th>Auto-renew &amp; actions</th>
426	              </tr>
427	            </thead>
428	            <tbody>
429	              {certificates.map((c) => (
430	                <tr key={c.id}>
431	                  <td className="max-w-sm font-medium text-slate-100">
432	                    {c.domain}
433	                    {c.lastError && (
434	                      <span
435	                        className={`mt-0.5 block text-xs font-normal ${
436	                          c.status === "FAILED" ? "text-red-400" : "text-amber-400"
437	                        }`}
438	                      >
439	                        {c.lastError}
440	                      </span>
441	                    )}
442	                  </td>
443	                  <td className="text-slate-400">{c.serverName ?? "—"}</td>
444	                  <td>
