10	const EXAMPLES = [
11	  "Install and configure nginx serving a simple landing page over HTTP.",
12	  "Set up Node.js LTS, PM2, and a UFW firewall allowing only SSH and HTTP/HTTPS.",
13	  "Install Docker and run a Postgres 16 container with a persistent volume.",
14	];
15	
16	const TERMINAL = new Set(["DONE", "FAILED"]);
17	
18	function parsePlan(raw?: string | null): PlanStep[] {
19	  if (!raw) return [];
20	  try {
21	    const p = JSON.parse(raw);
22	    if (Array.isArray(p)) {
23	      return p
24	        .map((s) => (typeof s === "string" ? { cmd: s } : { cmd: String(s?.cmd ?? ""), intent: s?.intent }))
25	        .filter((s) => s.cmd);
26	    }
27	  } catch {
28	    /* ignore */
29	  }
30	  return [];
31	}
