33	export function ClaudeBuilder({ servers }: { servers: ServerOption[] }) {
34	  const [serverId, setServerId] = useState(servers[0]?.id ?? "");
35	  const [prompt, setPrompt] = useState("");
36	  const [error, setError] = useState<string | null>(null);
37	  const [buildId, setBuildId] = useState<string | null>(null);
38	  const [state, setState] = useState<BuildState | null>(null);
39	  const [pending, startTransition] = useTransition();
40	  const logRef = useRef<HTMLPreElement>(null);
41	
42	  // Poll the build status while a build is active (until it reaches DONE/FAILED).
43	  useEffect(() => {
44	    if (!buildId) return;
45	    let alive = true;
46	    let timer: ReturnType<typeof setTimeout>;
47	
48	    const tick = async () => {
49	      try {
50	        const res = await fetch(`/api/claude/${buildId}`, { cache: "no-store" });
51	        if (res.ok) {
52	          const data = (await res.json()) as BuildState;
53	          if (alive) setState(data);
54	          if (data.status && TERMINAL.has(data.status)) return; // stop polling
55	        }
56	      } catch {
57	        /* transient — keep polling */
58	      }
59	      if (alive) timer = setTimeout(tick, 2000);
60	    };
61	    void tick();
62	    return () => {
63	      alive = false;
64	      clearTimeout(timer);
65	    };
66	  }, [buildId]);
67	
68	  // Keep the log scrolled to the bottom as it streams.
69	  useEffect(() => {
70	    if (logRef.current) logRef.current.scrollTop = logRef.current.scrollHeight;
71	  }, [state?.log]);
72	
73	  const status = state?.status ?? null;
74	  const inProgress = Boolean(buildId) && !(status && TERMINAL.has(status));
75	  const awaitingApproval = status === "AWAITING_APPROVAL";
76	  const planning = status === "QUEUED" || status === "PLANNING";
77	  const executing = status === "RUNNING";
78	  const plan = parsePlan(state?.plan);
79	
80	  const onSubmit = (e: React.FormEvent) => {
81	    e.preventDefault();
82	    setError(null);
83	    startTransition(async () => {
84	      const res = await submitBuild(serverId, prompt);
85	      if (res.error) {
86	        setError(res.error);
87	        return;
88	      }
89	      if (res.buildId) {
