137	      : "border-amber-500/40 bg-amber-500/10 text-amber-300";
138	
139	  return (
140	    <div className="space-y-6">
141	      <form onSubmit={onSubmit} className="card space-y-4 p-5">
142	        <div>
143	          <label className="mb-1.5 block text-sm font-medium text-slate-300">Server</label>
144	          <select
145	            className="input"
146	            value={serverId}
147	            onChange={(e) => setServerId(e.target.value)}
148	            disabled={inProgress || pending}
149	          >
150	            {servers.map((s) => (
