152	                {s.hostname}
153	              </option>
154	            ))}
155	          </select>
156	        </div>
157	
158	        <div>
159	          <label className="mb-1.5 block text-sm font-medium text-slate-300">
160	            What should Claude build?
161	          </label>
162	          <textarea
163	            className="input min-h-[110px] resize-y font-normal"
164	            placeholder="e.g. Install and configure a Node.js app served behind nginx with a firewall."
165	            value={prompt}
166	            onChange={(e) => setPrompt(e.target.value)}
