180	              </button>
181	            ))}
182	          </div>
183	        </div>
184	
185	        {error && <p className="text-sm text-red-300">{error}</p>}
186	
187	        <div className="flex items-center gap-3">
188	          <button
189	            type="submit"
190	            className="btn-primary"
191	            disabled={inProgress || pending || !serverId || prompt.trim().length < 8}
192	          >
193	            {pending && !buildId ? "Starting…" : inProgress ? "In progress…" : "Plan with Claude"}
194	          </button>
195	          {buildId && !inProgress && (
196	            <button type="button" onClick={reset} className="btn-secondary">
197	              New build
