229	
230	          {awaitingApproval && plan.length > 0 && (
231	            <div className="space-y-4">
232	              <div>
233	                <h3 className="text-sm font-semibold text-slate-200">Proposed plan</h3>
234	                <p className="mt-1 text-xs text-slate-500">
235	                  Review these {plan.length} command(s). They only run if you approve.
236	                </p>
237	              </div>
238	              <ol className="space-y-2">
239	                {plan.map((step, i) => (
240	                  <li
241	                    key={i}
