73	            onChange={(e) => setDomain(e.target.value)}
74	            placeholder="app.example.com"
75	            disabled={pending || noServers}
76	          />
77	        </div>
78	        <button
79	          className="btn-primary"
80	          disabled={pending || noServers || !serverId || domain.trim().length < 3}
81	          onClick={() =>
82	            start(async () => {
83	              setError(null);
84	              const res = await requestCertificate(serverId, domain.trim());
85	              if (res?.error) setError(res.error);
86	              else setDomain("");
87	            })
88	          }
89	        >
90	          {pending ? "Requesting…" : "Request certificate"}
91	        </button>
92	      </div>
93	      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
94	      {noServers && (
95	        <p className="mt-2 text-xs text-slate-500">
96	          You need a running server before you can request a certificate.
97	        </p>
98	      )}
99	    </div>
